using Contoso.Pricing;

namespace Contoso.Pricing.Tests;

[TestClass]
public sealed class PriceCalculatorTests
{
    private readonly PriceCalculator _calculator = new();

    // ─── CalculateTotal: DataRow (inline compile-time constants) ───

    [TestMethod]
    [DataRow(10.00, 1, 0.0, 10.00, DisplayName = "Single item, no tax")]
    [DataRow(10.00, 5, 0.0, 50.00, DisplayName = "Multiple items, no tax")]
    [DataRow(10.00, 1, 0.10, 11.00, DisplayName = "Single item, 10% tax")]
    [DataRow(25.00, 4, 0.20, 120.00, DisplayName = "Multiple items, 20% tax")]
    [DataRow(0.00, 10, 0.15, 0.00, DisplayName = "Zero price")]
    [DataRow(99.99, 0, 0.10, 0.00, DisplayName = "Zero quantity")]
    public void CalculateTotal_WithValidInputs_ReturnsExpected(
        double unitPrice, int quantity, double taxRate, double expected)
    {
        var result = _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate);

        Assert.AreEqual((decimal)expected, result);
    }

    // ─── CalculateTotal: DynamicData with ValueTuples (complex/decimal data) ───

    [TestMethod]
    [DynamicData(nameof(CalculateTotalData))]
    public void CalculateTotal_DynamicData_ReturnsExpected(
        decimal unitPrice, int quantity, decimal taxRate, decimal expected)
    {
        var result = _calculator.CalculateTotal(unitPrice, quantity, taxRate);

        Assert.AreEqual(expected, result);
    }

    public static IEnumerable<(decimal unitPrice, int quantity, decimal taxRate, decimal expected)> CalculateTotalData =>
    [
        (10.00m, 1, 0.00m, 10.00m),
        (10.00m, 5, 0.10m, 55.00m),
        (29.99m, 3, 0.08m, 97.1676m),
        (0.01m, 100, 1.00m, 2.00m),
    ];

    // ─── CalculateTotal: invalid-input tests ───

    [TestMethod]
    [DataRow(-1.00, 1, 0.10, DisplayName = "Negative unit price")]
    public void CalculateTotal_NegativePrice_Throws(double unitPrice, int quantity, double taxRate)
    {
        var ex = Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate));

        Assert.AreEqual("unitPrice", ex.ParamName);
    }

    [TestMethod]
    [DataRow(10.00, -1, 0.10, DisplayName = "Negative quantity")]
    public void CalculateTotal_NegativeQuantity_Throws(double unitPrice, int quantity, double taxRate)
    {
        var ex = Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate));

        Assert.AreEqual("quantity", ex.ParamName);
    }

    [TestMethod]
    [DataRow(10.00, 1, -0.01, DisplayName = "Tax rate below 0")]
    [DataRow(10.00, 1, 1.01, DisplayName = "Tax rate above 1")]
    public void CalculateTotal_InvalidTaxRate_Throws(double unitPrice, int quantity, double taxRate)
    {
        var ex = Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate));

        Assert.AreEqual("taxRate", ex.ParamName);
    }

    // ─── ApplyDiscount: DataRow ───

    [TestMethod]
    [DataRow(100.00, 10.0, 90.00, DisplayName = "10% off 100")]
    [DataRow(200.00, 25.0, 150.00, DisplayName = "25% off 200")]
    [DataRow(50.00, 0.0, 50.00, DisplayName = "No discount")]
    [DataRow(80.00, 100.0, 0.00, DisplayName = "100% discount")]
    [DataRow(49.99, 50.0, 24.995, DisplayName = "50% off 49.99")]
    public void ApplyDiscount_WithValidInputs_ReturnsExpected(
        double price, double discountPercent, double expected)
    {
        var result = _calculator.ApplyDiscount((decimal)price, (decimal)discountPercent);

        Assert.AreEqual((decimal)expected, result);
    }

    // ─── ApplyDiscount: DynamicData with ValueTuples ───

    [TestMethod]
    [DynamicData(nameof(ApplyDiscountData))]
    public void ApplyDiscount_DynamicData_ReturnsExpected(
        decimal price, decimal discountPercent, decimal expected)
    {
        var result = _calculator.ApplyDiscount(price, discountPercent);

        Assert.AreEqual(expected, result);
    }

    public static IEnumerable<(decimal price, decimal discountPercent, decimal expected)> ApplyDiscountData =>
    [
        (100.00m, 10.0m, 90.00m),
        (200.00m, 25.0m, 150.00m),
        (50.00m, 0.0m, 50.00m),
        (80.00m, 100.0m, 0.00m),
        (999.99m, 15.0m, 849.9915m),
    ];

    // ─── ApplyDiscount: invalid-input tests ───

    [TestMethod]
    [DataRow(100.00, -1.0, DisplayName = "Negative discount")]
    [DataRow(100.00, 101.0, DisplayName = "Discount over 100%")]
    public void ApplyDiscount_InvalidDiscount_Throws(double price, double discountPercent)
    {
        var ex = Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount((decimal)price, (decimal)discountPercent));

        Assert.AreEqual("discountPercent", ex.ParamName);
    }

    // ─── FormatPrice: DataRow ───

    [TestMethod]
    [DataRow(19.99, "$", "$19.99", DisplayName = "USD format")]
    [DataRow(19.99, "€", "€19.99", DisplayName = "EUR format")]
    [DataRow(0.00, "$", "$0.00", DisplayName = "Zero price")]
    [DataRow(1000.5, "$", "$1000.50", DisplayName = "Rounds to 2 decimals")]
    public void FormatPrice_WithSymbol_ReturnsFormattedString(
        double price, string symbol, string expected)
    {
        var result = _calculator.FormatPrice((decimal)price, symbol);

        Assert.AreEqual(expected, result);
    }
}

